@Override public byte[] evaluateResponse(final byte[] response) throws SaslException {
  byte[] challenge;
  switch (state) {
    case INITIAL: {
      try {
        challenge = generateServerFirstMessage(response);
      } catch (IllegalFormatException | IndexOutOfBoundsException | IllegalStateException | NullPointerException e) {
        throw new SaslException("Error generating server first message", e);
      }
      state = State.IN_PROGRESS;
      break;
    }
    case IN_PROGRESS: {
      try {
        challenge = generateServerFinalMessage(response);
      } catch (IllegalFormatException | IndexOutOfBoundsException | IllegalStateException | NullPointerException e) {
        throw new SaslException("Error generating server final message", e);
      }
      state = State.COMPLETE;
      break;
    }
    case COMPLETE:
      if (response == null || response.length == 0) {
        challenge = new byte[0];
        break;
      }
    default:
      throw new SaslException("No response expected in state " + state);
  }
  return challenge;
}
